let n = grid.len() as isize;
let mut ans = vec![std::isize::MAX; k as usize];
let mut visited = vec![vec![false; n as usize]; n as usize];
let directions = vec![(0, 1), (1, 0), (0, -1), (-1, 0)];

fn dfs(x: isize, y: isize, k: isize, grid: &Vec<Vec<isize>>, visited: &mut Vec<Vec<bool>>, ans: &mut Vec<isize>, path: &mut Vec<isize>, directions: &Vec<(isize, isize)>) {
    if k == 0 {
        if path.len() as isize == k {
            if path < ans {
                ans.clone_from(path);
            }
        }
        return;
    }
    for &(dx, dy) in directions.iter() {
        let nx = x + dx;
        let ny = y + dy;
        if nx >= 0 && nx < grid.len() as isize && ny >= 0 && ny < grid[0].len() as isize && !visited[nx as usize][ny as usize] {
            visited[nx as usize][ny as usize] = true;
            path.push(grid[nx as usize][ny as usize]);
            dfs(nx, ny, k - 1, grid, visited, ans, path, directions);
            path.pop();
            visited[nx as usize][ny as usize] = false;
        }
    }
}

for i in 0..n {
    for j in 0..n {
        visited[i as usize][j as usize] = true;
        let mut path = vec![grid[i as usize][j as usize]];
        dfs(i, j, k - 1, &grid, &mut visited, &mut ans, &mut path, &directions);
        visited[i as usize][j as usize] = false;
    }
}

